/* Logo 381 (v2): números quietos y tres corrientes de brisa que pasan por detrás.
   Cada onda es una capa 1.5x más ancha que el tile y se desplaza exactamente un periodo
   (33.333% de su ancho), así el bucle no tiene costura. Solo CSS `animation` sobre
   transform + opacity: compositor, sin JS. La regla global de prefers-reduced-motion
   las congela en su pose base, que es idéntica al ícono estático. */
.logo381{
  --logo381-bg:#101014;
  position:relative; flex:none; width:34px; height:34px; border-radius:10px;
  background:var(--logo381-bg); box-shadow:inset 0 0 0 1px rgba(90,200,250,0.14);
  overflow:hidden; isolation:isolate; contain:strict;
}
.logo381__brisa{
  position:absolute; inset:0;
  -webkit-mask-image:linear-gradient(90deg, transparent, #000 22%, #000 78%, transparent);
          mask-image:linear-gradient(90deg, transparent, #000 22%, #000 78%, transparent);
}
.logo381__onda{
  position:absolute; top:0; left:0; width:150%; height:100%; display:block; overflow:visible;
  fill:none; stroke-linecap:round; opacity:var(--o);
  animation:logo381-brisa var(--t) linear infinite, logo381-soplo calc(var(--t) * .62) ease-in-out infinite;
  will-change:transform, opacity;
}
@keyframes logo381-brisa{ from{ transform:translateX(-33.3333%); } to{ transform:translateX(0); } }
@keyframes logo381-soplo{ 0%,100%{ opacity:var(--o); } 50%{ opacity:calc(var(--o) * .45); } }
.logo381__num{ position:absolute; inset:0; width:100%; height:100%; display:block; fill:none; stroke-linecap:round; stroke-linejoin:round; }
.logo381__halo{ stroke:var(--logo381-bg); }
